import mpmath as mp

mp.mp.dps = 50
iv = mp.iv
iv.dps = 40

def X0_iv(A,B):
    return iv.sin(B)*iv.cos(A)/(2*iv.sin(A+B))

def beta0_iv(A):
    return (iv.pi - A)/3

def RHS_iv(A,B):
    b0 = beta0_iv(A)
    Kc = 2*iv.sin(A)*iv.sin(A+B)
    P = iv.sin(A-B)/2 + 3*iv.sin(A+B)/2
    Q = -iv.sin(A)*iv.sin(B)
    G = Kc - P*iv.sin(b0) - Q*iv.cos(b0)
    return (1+iv.cos(B))*iv.cos(b0) - iv.sin(b0)*G

def Aof_iv(B):
    t = -iv.sin(B)*iv.cos(2*B)/(2*iv.cos(B)**3)
    return iv.atan2(t,1)

def D1_iv(B):
    A = Aof_iv(B)
    return (1+iv.cos(B))*iv.cos(B) - RHS_iv(A,B)

# point evaluation sanity
Bstar_f = mp.mpf('0.9117382909684876363584895643167312071753892163922')
pi3_f = mp.pi/3

def to_iv_point(x):
    return iv.mpf(x)

print("D1 at Bstar (point iv):", D1_iv(to_iv_point(Bstar_f)))
print("D1 at pi/3 (point iv):", D1_iv(iv.pi/3))
