import mpmath as mp
mp.mp.dps = 60

# raw definitions
def X0(A,B):
    return mp.sin(B)*mp.cos(A)/(2*mp.sin(A+B))

def beta0(A):
    return (mp.pi - A)/3

def Kc(A,B):
    return 2*mp.sin(A)*mp.sin(A+B)

def P(A,B):
    return mp.sin(A-B)/2 + 3*mp.sin(A+B)/2

def Q(A,B):
    return -mp.sin(A)*mp.sin(B)

def G(A,B,beta):
    return Kc(A,B) - P(A,B)*mp.sin(beta) - Q(A,B)*mp.cos(beta)

def RHS(A,B):
    b0 = beta0(A)
    return (1+mp.cos(B))*mp.cos(b0) - mp.sin(b0)*G(A,B,b0)

def D1(A,B):
    return (1+mp.cos(B))*mp.cos(B) - RHS(A,B)

# find A* : the corner where G(beta0(A)) = 0  (star-corner lemma)
